-- Invoice owner workflow and platform review listing.
create or replace function public.list_subscription_plans() returns setof public.subscription_plans language sql security definer set search_path=public as $$ select p from public.subscription_plans p where p.is_active order by p.price_monthly,p.name; $$;
create or replace function public.list_organization_invoices(p_organization_id uuid) returns setof public.subscription_invoices language sql security definer set search_path=public as $$ select i from public.subscription_invoices i where i.organization_id=p_organization_id and exists(select 1 from public.organization_members om where om.organization_id=i.organization_id and om.user_id=auth.uid() and om.status='active' and om.role_code in ('organization_owner','organization_admin')) order by i.created_at desc; $$;
create or replace function public.platform_list_invoices() returns setof public.subscription_invoices language sql security definer set search_path=public as $$ select i from public.subscription_invoices i where public.has_role(auth.uid(),'platform_admin') order by i.created_at desc; $$;
create or replace function public.submit_payment_proof(p_invoice_id uuid,p_file_path text,p_transferred_amount numeric default null,p_transferred_at timestamptz default null,p_sender_name text default null,p_note text default null) returns boolean language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from public.subscription_invoices i join public.organization_members om on om.organization_id=i.organization_id where i.id=p_invoice_id and om.user_id=auth.uid() and om.status='active' and om.role_code in ('organization_owner','organization_admin')) then raise exception 'Akses invoice ditolak' using errcode='42501'; end if; insert into public.payment_proofs(invoice_id,file_path,transferred_amount,transferred_at,sender_name,note,submitted_by) values(p_invoice_id,p_file_path,p_transferred_amount,p_transferred_at,p_sender_name,p_note,auth.uid()); update public.subscription_invoices set status='proof_submitted',updated_at=now() where id=p_invoice_id; return true; end; $$;
revoke all on function public.list_subscription_plans(), public.list_organization_invoices(uuid), public.platform_list_invoices(), public.submit_payment_proof(uuid,text,numeric,timestamptz,text,text) from public, anon;
grant execute on function public.list_subscription_plans(), public.list_organization_invoices(uuid), public.platform_list_invoices(), public.submit_payment_proof(uuid,text,numeric,timestamptz,text,text) to authenticated;
